WITH supplier_stats AS (SELECT supplier_id, SUM(stock_qty) AS total_stock_qty, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(category))) AS category_values FROM products WHERE stock_qty = 356 GROUP BY supplier_id) SELECT suppliers.id, suppliers.supplier_name, supplier_stats.total_stock_qty, supplier_stats.category_values FROM suppliers INNER JOIN supplier_stats ON suppliers.id = supplier_stats.supplier_id WHERE supplier_stats.total_stock_qty >= 700
